		for(int i = 0; i < n-1; i++){
			for(int j = n-1; j >= i+1; j--){
				if(c[j]  < c[j-1]){
					int tmp = c[j];
					c[j] = c[j-1];
					c[j-1] = tmp;
					count++;
				}
			}
		}
