		int q = Integer.parseInt(s);
		int[] t = new int[q];
		s = in.readLine();
		as = s.split(" ");
		for(int i = 0; i < q; i++) {
			t[i] = Integer.parseInt(as[i]);
		}
		int count = 0;
		for(int i = 0; i < q; i++) {
			int left = 0;
			int right = n-1;
			int mid = (left + right) / 2;
			while (left <= right) {

				if(a[mid] == t[i]) {
					count++;
					break;
				} else if(a[mid] < t[i]) {
					 left = mid+1;
					 mid = (left + right) / 2;
				} else if(a[mid] > t[i]) {
					right = mid-1;
					mid = (left + right) / 2;
				}
			}
		}
		System.out.println(count);
	}


}

