                if (( n[j] % 10 ) == 0) {
                    min = ( 10 - ( n[j] % 10 ) );
                    index = j;                    
                } else if ( ( 10 - ( n[j] % 10 ) ) <= min )  {
                    min = ( 10 - ( n[j] % 10 ) );
                    index = j;
                }
            }
            swap = n[i];
            n[i] = n[index];
            n[index] = swap;
        }

        for ( int i = 0 ; i < 5 ; i++ ) {
            if (i < 4){ 
