            exl[r][j] = 0;
            for(i = 0; i < r; i++){ exl[r][j] += exl[i][j]; }
        }
        for(i = 0; i <= r; i++){ show(exl[i]); }
    }
    public static void show(int[] a){
        int n = a.length;
        for(int i = 0; i < n - 1; i++){ System.out.print(a[i] + " "); }
