public class Main {

	public int search(int[] s, int value) {
		int left = 0;
		int right = s.length - 1;
		while( left <= right) {
			int med = (left+right) / 2;

			if(value == s[med]) {
				return 1;
			}
			if(value < s[med]) {
				right = med - 1;
			}
			else {
				left = med + 1;
			}
		}
		return 0;
	}


