    static class TaskC {

        public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {   
        	int t=1;
        	while(t-->0) {

        		int n=in.nextInt();
        		String s=in.nextLine();

        		char[] a=s.toCharArray();
        		long res=1;
        		for(int i=1;i<n;i++) {
        			if(a[i]!=a[i-1]) {
