		String s1 = r.readLine();
		long num = Long.valueOf(s1.split(" ")[0]);
		long count = Long.valueOf(s1.split(" ")[1]);
		double val = 0.0d;

		double kitei = ((double)1 / num);
		for (long i = 1; i <= num; i++) {
			if (i >= count) {
				val += kitei;
				continue;
			}

			double v = 1;
			long v2 = i;
