		Scanner stdIn = new Scanner(System.in);

		int d, t, s;
		d = stdIn.nextInt();
		t = stdIn.nextInt();
		s = stdIn.nextInt();
		boolean result = solve(d, t, s);
		if(result)
			System.out.println("Yes");
		else
			System.out.println("No");

		stdIn.close();
	}
}

