						end = i - 1;
					}

					long min = 0;
					for (int j = start; j <= end; j++) {
						if (min == 0 || min > hana[j]) {
							min = hana[j];
						}

					}
					for (int j = start; j <= end; j++) {
						hana[j] = hana[j] - min;
					}
					b = false;
					start = 0;
					end = 0;
					answer += min;
				}
			}

			boolean has = false;
			for (int i = 0; i < hana.length; i++) {
				if (hana[i] > 0) {
					has = true;
					break;
				}
			}

			if (!has) {
				System.out.println(answer);
				return;
			}
		}

	}
}

