        Scanner r = new Scanner(System.in);

        //Reader r = new Reader();

        //int t = Integer.parseInt(r.nextLine());
        //int t = r.nextInt();

        int a = r.nextInt();
        int b = r.nextInt();

        System.out.println(a*b);




    }


}

