		int ans = 0;
		if (A_B > C * 2) {
			ans = C * p_S.getnum() * 2;
		} else {
			ans = A_B * p_S.getnum();
		}

		int n = p_B.getnum() - p_S.getnum();

		if (p_B.getmoney() > C * 2) {
			ans = ans + n * C * 2;
		} else {
			ans = ans + n * p_B.getmoney();
		}

		System.out.println(ans);
		sc.close();

	}
}

