        String s = fs.nextLine();
        Stack<Integer> st = new Stack<Integer>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '0' || s.charAt(i) == '1') {
                st.push(s.charAt(i) - '0');
            } else {
