        int cnt=0;
        double sum=0;
        double mean;
        while(true){
            int n;
            n = sc.nextInt();
            if(n == 0)
                break;
            sum=0;
            mean=0;
            double[] s = new double[n];
            for(int i=0; i<n; i++){
