              intArray.remove(j);
              j--;
            }else if( intArray.get(j) == x-i ){
              lowExist = true;
              intArray.remove(j);
              j--;
            }

            if( highExist && lowExist ){
              break;
            }

          }
          if( !(highExist && lowExist) ){
