  static long maxx(int[] arr,int ind,int k){
  	if(ind==arr.length-1){
    	return 0;
    }
    if(aa[ind]!=-1){return aa[ind];}
    long maxs=Integer.MAX_VALUE;
    for(int j=1;j<=k;j++){
