                while(cnt > 0){


                    long tempNum = (long)Math.pow(26, cnt);
                    long alphabat = number/tempNum; // 0이라면 그냥 a
                    char part = (char) (alphabat+97);
                    number -= (tempNum)*alphabat;


                    name += part;

                    if(cnt ==1){
                        alphabat = number%26;
                        part = (char) (alphabat+97);
                        name += part;
                    }

                    cnt--;
                }

                break;
            }
            cnt++;
        }
        System.out.println(name);
    }
}

