	static boolean isPrime(int num) {
		if (num == 2) {
			return true;
		}
		if (num < 2 || num % 2 == 0) {
			return false;
		}
		int i = 3;
		while (i <= Math.sqrt(num)) {
			if (num % i == 0) {
				return false;
			}
			i = i + 2;
		}
		return true;
	}
