			}
			else{
				temp=x[0];
				x[0]=x[1]%x[0];
				x[1]=temp;
			}
			}

			y[0] /= gcd;
			y[1] /= gcd;
			lcm = y[0] * y[1] * gcd;
			System.out.println(gcd + " " + lcm);
		}
	}
}

