			num=num-time;
			if(num<=0) {
				total=total+time+num;
				System.out.print(name1+" ");
				System.out.println(total);
				if(name.isEmpty()) {
					break;
				}
			}else {
				total=total+time;
				queue.add(num);
				name.add(name1);
			}
		}
		scanner.close();
	}

}

