        int tmp=0;
        boolean flag = true;
        while (flag){
            flag = false;
            for ( int j = n-1;j > 0; j--){
                if ( A[j] < A[j-1] ) {
                    tmp    = A[j-1];
                    A[j-1] = A[j];
