			while(u - l > 1) {
				int m = (u + l) / 2;	
				if(t == S[m]) { 
					count++;
					break;
				} else if (t < S[m]) {
					u = m;
				} else {
					l = m;
				}
			}
		}
		System.out.println(count);
	}
