		long n = sc.nextLong();
		for (long i = (long) Math.sqrt(n); i > 0; i--) {
			if (n % i == 0) {
				out.println(digit(n / i));
				break;
			}
		}

		out.flush();
	}

	static int digit(long n) {
		int d = 0;
		while (n > 0) {
			n /= 10;
			d++;
		}
		return d;
	}

