import java.util.*;

public class Main{
	static int search(int[] l,int key){
		int left = 0 ;
		int right = l.length;
		int mid ;

		while(left < right){
			mid = (left + right) / 2 ;
			if(l[mid] == key){
				return mid;
			}
			else if(l[mid] < key){
				left = mid +1 ;
			}
			else if(key < l[mid]){
				right = mid;
			}
		}
		return -1 ;
	}

	public static void main(String[] args){
	    Scanner scanner = new Scanner(System.in);

	    int n = scanner.nextInt();
	    int[] l = new int[n];
	    for(int i = 0; i < n; i++){
				l[i]=scanner.nextInt();
			}

	    int q = scanner.nextInt();
	    int sum = 0;

	    for(int i = 0; i < q; i++){
	        if(search(l, scanner.nextInt() ) >= 0){
						sum++;
					}
	    }

	    System.out.println(sum);
	}
}

import java.util.ArrayDeque;
import java.util.List;
import java.util.Scanner;

class Submission {
  int id;
  boolean ac;
}

public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();

    Submission[] subs = new Submission[M];
    for (int i=0; i<M; i++) {
      int id = sc.nextInt();
      String ac = sc.next();
      subs[i] =  new Submission();
      subs[i].id = id - 1;
      subs[i].ac = "AC".equals(ac);  
    }

    boolean[] acs = new boolean[N];
    int[] penalties = new int[N];
    for (int i=0; i<N; i++) {
      acs[i] = false;
      penalties[i] = 0;
    }

    for (int i=0; i<M; i++) {
      Submission sub = subs[i];
      if (acs[sub.id]) {
        continue;
      } else if (sub.ac) {
        acs[sub.id] = true;
      } else {
        penalties[sub.id] += 1;
      }
    }

    int ac = 0;
    int penalty = 0;
    for (int i=0; i<N; i++) {
      if (acs[i]) {
        ac += 1;
        penalty += penalties[i];
      }
    }

    sc.close();
    System.out.println(ac + " " + penalty);
  }
}

