    public static boolean binarySearch(int[] A,int key){
    	int left = 0;
    	int right = A.length;
    	int mid = 0;
    	while(left < right){
    	    mid = (left + right) / 2;

    	    if(A[mid] == key){
    		return true;
    	    }else if(key < A[mid]){
    		right = mid;
    	    }else{
    		left = mid + 1;
    	    }
    	}
    	return false;
    }
}

