    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int A[] = new int[123];
            for (int i = 0; i <= 100; i++)
                A[i] = 0;
            for (int foo = 0; foo < 2; foo++) {
