		ArrayList<ArrayList<Integer>> point = new ArrayList<ArrayList<Integer>>();

		int n = sc.nextInt();
		int d = sc.nextInt();

		for(int i = 0; i < n ; i++) {
			ArrayList<Integer> array = new ArrayList<Integer>();

