                }else{
                    sum += x*a;
                }
            }else{
                sum += x * 2 *c;
                y = y-x;
                if(b > c*2){
                    sum += y * 2* c;
                }else{
                    sum += y*b;
                }
            }
        }else{
            sum = a*x + b*y;
        }
