		return (num % 2) != 0 ? true : false;
	}

	public static int getInteger(int num) {
		if(isOddNumber(num)) {
			return (3 * num) + 1;
		}

		return num / 2;
	}

	public static int getResult(int num) {
		if(isMaxNum(num)) {
			return 0;
		}

		String[] temp = new String[1000000];

		//boolean notFound = true;
		int index = 1;
