public class Main {

    public static void main(String[] args)
    {
	    Set<Integer> set = new HashSet();
	    int a = getInput();
        do {
            set.add(a);
            a = f(a);
        } while (!set.contains(a));
        System.out.println(set.size() + 1);
        return;
    }

    private static int f(int n)
    {
        if (n % 2 == 0) {
            return n / 2;
        } else {
            return 3 * n + 1;
        }
    }

