class Stack {
	private int num[];
	private int top;

	Stack(int arg_size){
		num = new int[arg_size];
		top = 0;
	}

	public void push(int x) {
		num[top++] = x;
	}

	public int pop() {
		top--;
		return num[top];
	}

	public boolean isEmpty() {
		return top == 0;
	}
}

