        int[] a = new int[N];
        String[] s = br.readLine().split(" ");
        for(int i = 0;i<N;i++){
            a[i] = Integer.parseInt(s[i]);
        }

        int Nswap = 0;
        for(int i=0;i<N;i++){
            for(int j = N-1;j>=i+1;j--){
                if(a[j]<a[j-1]){
                    int tmp = a[j];
                    a[j]=a[j-1];
